import numpy as np

def feature(pos, targets, values, rates, battery, drain, charge_rate, charger, time, time_left, history):
    """-1 for candidates whose straight-line flight would exceed the battery, else 0 (charger stays 0)."""
    d = np.linalg.norm(targets - pos, axis=1)
    infeasible = (d * drain) > battery
    return np.where(infeasible, -1.0, 0.0)

import numpy as np

def feature(pos, targets, values, rates, battery, drain, charge_rate, charger, time, time_left, history):
    """Burst-gated proximity: 0 unless recent value-appearance rate exceeds 5% of the run average, else -(d - dmin)/(dmax - dmin) in [-1, 0]."""
    k = targets.shape[0]
    s = history.shape[0]
    if s == 0:
        return np.zeros(k)
    lam_avg = np.sum(history[:, 3]) / max(time, 1.0)
    w = min(time, 10.0)
    recent = history[history[:, 2] >= time - 10.0, 3]
    lam_rec = np.sum(recent) / max(w, 1.0)
    burst = lam_rec - lam_avg
    if burst <= 0.05 * lam_avg:
        return np.zeros(k)
    d = np.sqrt(np.sum((targets - pos[None, :]) ** 2, axis=1))
    dmin = d.min()
    dmax = d.max()
    return -(d - dmin) / (dmax - dmin + 1e-9)
